arguments.prompt:
You are implementing a shipment tracking Blazor Web App. The project has already been scaffolded at `/tmp/sv-4a40a43dbfe9431ea3dc68bd34d7f6cf/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

The project structure:
- `ShipmentTracker/` (server project)
- `ShipmentTracker.Client/` (WebAssembly client project)
- Solution file: `ShipmentTracker.sln`

This is Interactive Auto with Global interactivity. Key rules:
- All interactive components MUST go in the `.Client` project
- Interactive components cannot access DB directly — use HTTP APIs
- Define service interfaces in `.Client`, implement with HttpClient there
- Server implements the same interface with direct data access
- Both Program.cs must register matching services
- No need to add `@rendermode` to pages (global mode handles it)

## What to implement:

### 1. Remove template pages
Delete `Counter.razor` and `Weather.razor` from `ShipmentTracker.Client/Pages/`.

### 2. Create shared models in `ShipmentTracker.Client/Models/`

**Shipment.cs:**
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create service interface in `ShipmentTracker.Client/Services/IShipmentService.cs`

```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create client-side implementation in `ShipmentTracker.Client/Services/ShipmentServiceClient.cs`

```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await _http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await _http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}
```

### 5. Create server-side implementation in `ShipmentTracker/Services/ShipmentServiceServer.cs`

This uses an in-memory list for demo purposes (could be replaced with EF Core later):

```csharp
namespace ShipmentTracker.Services;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public class ShipmentServiceServer : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = new DateTime(2026, 7, 1), EstimatedDelivery = new DateTime(2026, 7, 10), CustomerEmail = "alice@example.com", Description = "Electronics - Laptop" },
        new Shipment { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, ShippedDate = new DateTime(2026, 6, 25), EstimatedDelivery = new DateTime(2026, 7, 7), CustomerEmail = "bob@example.com", Description = "Furniture - Office Desk" },
        new Shipment { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = new DateTime(2026, 7, 5), EstimatedDelivery = new DateTime(2026, 7, 18), CustomerEmail = "carol@example.com", Description = "Medical Supplies" },
        new Shipment { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, ShippedDate = new DateTime(2026, 6, 20), EstimatedDelivery = new DateTime(2026, 7, 3), CustomerEmail = "dave@example.com", Description = "Automotive Parts" },
        new Shipment { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, BR", Destination = "Toronto, CA", Status = ShipmentStatus.Delayed, ShippedDate = new DateTime(2026, 6, 28), EstimatedDelivery = new DateTime(2026, 7, 12), CustomerEmail = "eve@example.com", Description = "Textiles - Fabric Rolls" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment != null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}
```

### 6. Create API endpoints

Add a file `ShipmentTracker/ShipmentEndpoints.cs`:

```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (IShipmentService service) =>
            await service.GetAllShipmentsAsync())
            .RequireAuthorization();

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).RequireAuthorization();

        group.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            await service.UpdateShipmentStatusAsync(id, status);
            return Results.NoContent();
        }).RequireAuthorization();
    }
}
```

### 7. Create Dispatcher page in `ShipmentTracker.Client/Pages/Dispatch.razor`

```razor
@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>Dispatch Dashboard</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>ETA</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToShortDateString()</td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status" @onchange="(e) => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-secondary"
    };
}
```

### 8. Create Customer tracking page in `ShipmentTracker.Client/Pages/Track.razor`

```razor
@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-2026)" @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isSearching">
                @if (isSearching)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                }
                else
                {
                    <span>Track</span>
                }
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && shipment == null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number "<strong>@searchedNumber</strong>". Please check and try again.
    </div>
}

@if (shipment != null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>
                        <dt>Shipped Date</dt>
